mapper.select:
select * from store_member
where store_id = #{storeId}
  and user_id = #{userId}
  and deleted = 0
limit 1

mapper.insert:
insert into store_member (
    id, store_id, user_id, is_member, balance, created_time, update_time, deleted
) values (
    #{id}, #{storeId}, #{userId}, #{isMember}, #{balance}, #{createdTime}, #{updateTime}, #{deleted}
)

mapper.update:
update store_member
set is_member = #{isMember},
    update_time = #{updateTime}
where store_id = #{storeId}
  and user_id = #{userId}
  and deleted = 0

update store_member
set balance = balance - #{amount},
    update_time = #{updateTime}
where store_id = #{storeId}
  and user_id = #{userId}
  and deleted = 0
  and is_member = 1
  and balance >= #{amount}

update store_member
set balance = balance + #{amount},
    update_time = #{updateTime}
where store_id = #{storeId}
  and user_id = #{userId}
  and deleted = 0

update store_member
set is_member = 1,
    balance = balance + #{amount},
    update_time = #{updateTime}
where store_id = #{storeId}
  and user_id = #{userId}
  and deleted = 0
